using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class OfficerLoopTests
{
    static WorldSession New(bool refuses=false)=>new(OfficerLoop.Create(refuses));
    static void Mission(WorldSession s,bool levy=false,string id="request:mission")=>Assert.Equal(ResultCode.Accepted,s.Submit(OfficerLoop.Mission(s.DiagnosticSnapshot(),id,levy),s.Revision).Code);
    [Fact] public void DifferentPeopleWorkTogetherButCannotLeaveDuringPendingWork(){var s=New();Mission(s);Mission(s,true,"request:levy");Assert.NotEqual(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);s.AdvanceTo(5);Assert.NotEqual(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);s.AdvanceTo(8);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);Assert.Equal(40,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==ContractFixture.Treasury).Quantity);}
    [Fact] public void SameActorCannotBookTwoPendingMainActions(){var s=New();Mission(s);var before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.NotEqual(ResultCode.Accepted,s.Submit(OfficerLoop.Mission(s.DiagnosticSnapshot(),"request:other",false),s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));Assert.NotEqual(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:travel","fork"),s.Revision).Code);}
    [Fact] public void LevyResultStaysUnknownUntilReportArrives(){var s=New();Mission(s,true);Assert.Contains(s.GetActorView(ContractFixture.Officer).Tasks,t=>t.KnownStatus=="発送済・結果未確認");s.AdvanceTo(5);Assert.Contains(s.GetActorView(ContractFixture.Officer).Tasks,t=>t.KnownStatus=="発送済・結果未確認");s.AdvanceTo(8);Assert.DoesNotContain(s.GetActorView(ContractFixture.Officer).Tasks,t=>t.KnownStatus=="発送済・結果未確認");}
    [Fact] public void DuplicateMissionDoesNotTransferTwice(){var s=New();var i=OfficerLoop.Mission(s.DiagnosticSnapshot(),"request:levy",true);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);s.AdvanceTo(8);Assert.Equal(ResultCode.AlreadyAccepted,s.Submit(i,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Transfers);Assert.Equal(40,s.DiagnosticSnapshot().Transfers.Single().Amount);}
    [Fact] public void CouncilDoesNotStopTimeOrTeleportRecipient(){var s=New();s.SetRegionalActive(true,s.Revision);var before=s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Clerk).Select(u=>u.Position).ToArray();var r=OfficerLoop.CouncilLine(s.DiagnosticSnapshot(),"request:council");Assert.Equal(ResultCode.Accepted,s.IssueRegional(r,s.Revision).Code);Assert.Equal(before,s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Clerk).Select(u=>u.Position));Assert.Equal("発送済・結果未確認",RegionalBattle.Status(s.DiagnosticSnapshot(),s.DiagnosticSnapshot().Region!.Commands.Single(),ContractFixture.Officer));s.AdvanceTo(150);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands.Single().Result);Assert.False(s.Paused);}
    [Theory][InlineData(2)][InlineData(5)][InlineData(25)] public void SaveRestoreRetainsTasksOrdersAndEffectOnce(int at){var s=New();Mission(s,true);if(at>=25){s.AdvanceTo(8);s.SetRegionalActive(true,s.Revision);s.IssueRegional(OfficerLoop.CouncilLine(s.DiagnosticSnapshot(),"request:council"),s.Revision);}s.AdvanceTo(at);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"loop-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(.25,10));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("stage"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(200);host.Current.AdvanceTo(200);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0})),ContractJson.Write(host.Current.DiagnosticSnapshot().Tasks.Select(t=>t with{Revision=0})));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Messaging),ContractJson.Write(host.Current.DiagnosticSnapshot().Messaging));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Region),ContractJson.Write(host.Current.DiagnosticSnapshot().Region));Assert.Single(host.Current.DiagnosticSnapshot().Transfers);}
    [Fact] public void RefusalIsReportedWithoutApplyingFormation(){var s=New(true);s.SetRegionalActive(true,s.Revision);s.IssueRegional(OfficerLoop.CouncilLine(s.DiagnosticSnapshot(),"request:council"),s.Revision);s.AdvanceTo(150);var w=s.DiagnosticSnapshot();Assert.Equal("refused",RegionalBattle.Status(w,w.Region!.Commands.Single(),ContractFixture.Officer));Assert.All(w.Region.Units.Where(u=>u.Commander==ContractFixture.Clerk),u=>Assert.Equal(u.Home,u.Position));}
    [Fact] public void NoLevyOutsideItsSiteOrInField(){var s=New();s.SetRegionalActive(true,s.Revision);Assert.NotEqual(ResultCode.Accepted,s.Submit(OfficerLoop.Mission(s.DiagnosticSnapshot(),"request:levy",true),s.Revision).Code);}
    [Fact] public void IndependentOldProfileIsNotRelabeled(){var old=ContinuousWorld.Create();Assert.False(OfficerLoop.Enabled(old));Assert.NotEqual(old.Definitions.Version,OfficerLoop.Create().Definitions.Version);}
    [Fact] public void MovingBeforeReturnReportDoesNotRevealOfficersDecision(){var s=New();s.SetRegionalActive(true,s.Revision);s.IssueRegional(OfficerLoop.CouncilLine(s.DiagnosticSnapshot(),"request:council"),s.Revision);s.AdvanceTo(45);s.IssueRegional(new(new("request:leave"),ContractFixture.Officer,ContractFixture.Officer,RegionalAction.Move,ContinuousWorld.Point("castle",65000,-85000),ContinuousWorld.Point("castle",85000,-85000)),s.Revision);s.AdvanceTo(150);var w=s.DiagnosticSnapshot();Assert.Equal("applied",w.Region!.Commands.First().Result);Assert.Equal("発送済・結果未確認",RegionalBattle.Status(w,w.Region.Commands.First(),ContractFixture.Officer));Assert.Contains(w.Messaging.Attempts,a=>a.FailureAt!=null);}
    [Fact] public void CouncilDisplayIsOptionalAndRoundtrips(){var p=new SavePresentation(.25,10,CouncilOpen:true);Assert.Equal(p,ContractJson.Read<SavePresentation>(ContractJson.Write(p)));Assert.Null(ContractJson.Read<SavePresentation>(System.Text.Encoding.UTF8.GetBytes("{\"DisplayFraction\":0,\"DisplaySpeed\":1}")).CouncilOpen);}
}
